	return array(
		array( 'Hardtail (Trek Marlin 7)', 45 ),
		array( 'Gravel (Salsa Journeyman)', 60 ),
		array( 'Kids 24in', 35 ),
		array( 'E-bike (Specialized Turbo Vado)', 85 ),
